/* the Swordbell mark (a sword whose guard is a loaded barbell), pixel art */
const MARCA_PNG = 'data:image/webp;base64,';
/* ---------- chrome: people, tabs, language, toast, sheet ---------- */
function corDe(pid) { const i = S.ordem.indexOf(pid); return CORES[(i < 0 ? 0 : i) % CORES.length]; }
function avatar(pid, cls = 'av') { const p = S.perfis[pid]; return `<span class="${cls}" style="background:${corDe(pid)}">${esc(((p && p.nome) || '?').trim().charAt(0).toUpperCase())}</span>`; }
function renderPeople() {
  const el = $('#people');
  $('#brandSub').textContent = t('app_sub');
  const mk = $('#brandMk'); if (mk && !mk.src) mk.src = MARCA_PNG;
  $('#langBtn').innerHTML = I.gear + '<span>' + LANG().toUpperCase() + '</span>';
  $('#langBtn').setAttribute('aria-label', t('settings'));
  if (!S.ready || !S.ordem.length) { el.innerHTML = ''; return; }
  const so = S.ordem.length > 1;
  el.innerHTML = S.ordem.map(pid => { const n = esc(S.perfis[pid].nome); return `<button class="who${so ? ' so' : ''}" data-a="me" data-pid="${esc(pid)}" aria-pressed="${pid === S.me}" aria-label="${n}" title="${n}">${avatar(pid)}${so ? '' : `<span class="nm">${n}</span>`}</button>`; }).join('');
  ajustarPessoas();
}
/* the person's name beside the title: when it doesn't fit, only the round initial shows, never a name cut in half */
function ajustarPessoas() {
  const el = $('#people');
  if (!el) return;
  el.classList.remove('compacto');
  if (el.children.length && el.scrollWidth > el.clientWidth + 1) el.classList.add('compacto');
}
addEventListener('resize', ajustarPessoas);
try { document.fonts.addEventListener('loadingdone', ajustarPessoas); } catch { /* no font events here */ }
const TABS = [['hoje', 'tab_today'], ['plano', 'tab_plan'], ['cardio', 'cardio'], ['coach', 'tab_coach'], ['jornada', 'tab_journey']];
const TAB_ICON = { hoje: I.hoje, plano: I.plano, cardio: SV('<path d="M3 12h4l2.5-6 4 12 2.5-6H21"/>'), coach: I.coach, jornada: I.jornada };
Object.assign(STR, { cardio: ['Cardio', 'Cardio', 'Cardio'] });
function renderTabs() {
  const show = S.ready && !!S.me && !S.sub;
  $('#tabs').hidden = !show;
  if (!show) return;
  $('#tabsIn').innerHTML = TABS.map(([id, k]) => `<button class="tab" data-a="tab" data-tab="${id}"${S.tab === id ? ' aria-current="page"' : ''}>${TAB_ICON[id]}<span>${t(k)}${id === 'hoje' && S.live ? `<i class="live" aria-label="${t('workout_live')}"></i>` : ''}</span></button>`).join('');
}
function abrirIdioma() {
  openSheet(t('language'), `<div class="stack">${LANGS.map(([c, n]) => `<button class="opt" data-a="setIdioma" data-v="${c}" aria-pressed="${LANG() === c}"><b>${n}</b></button>`).join('')}<p class="small muted">${t('language_note')}</p></div>`);
}
function trocarIdioma(code) {
  setLang(code); LS.set('td_lang', code);
  const p = perfil();
  if (p && S.canWrite && p.lang !== code) { const np = { ...p, lang: code }; S.perfis[S.me] = np; Store.set('perfis/' + S.me, np).catch(() => {}); }
  closeSheet(); render();
}
let toastT;
function toast(msg) { if (!msg) return; const el = $('#toast'); el.textContent = msg; el.hidden = false; clearTimeout(toastT); toastT = setTimeout(() => { el.hidden = true; }, 4200); }
const Sheet = { onClose: null };
function openSheet(title, body, onClose) {
  if (!$('#sheet').hidden) closeSheet();
  $('#sheetP').innerHTML = `<div class="sheet-h wrap"><div class="grab"></div><div class="row"><h2 class="h3" id="sheetTitle">${esc(title)}</h2><button class="x" data-a="fecharSheet" aria-label="${t('close')}">${I.x}</button></div></div><div class="wrap" id="sheetBody">${body}</div>`;
  $('#sheet').hidden = false; Sheet.onClose = onClose || null;
  document.documentElement.style.overflow = 'hidden';
}
function sheetBody(html) { const b = $('#sheetBody'); if (b) b.innerHTML = html; }
function closeSheet() {
  if ($('#sheet').hidden) return;
  $('#sheet').hidden = true; if (!P.on) document.documentElement.style.overflow = '';
  const f = Sheet.onClose; Sheet.onClose = null; if (f) f();
  tourAgendar();
}

/* ---------- the barbell: one plate per week, colored like competition plates ---------- */
const FASE_COR = { adapt: 'var(--plate-green)', accum: 'var(--plate-blue)', intens: 'var(--plate-red)', deload: 'var(--plate-white)' };
const FASE_H = { adapt: 44, accum: 54, intens: 64, deload: 32 };
function barbell(semanas, atual, todasFeitas) {
  const W = 340, H = 96, cy = 42, pw = 20, gap = 8;
  const x0 = Math.round((W - semanas.length * (pw + gap) + gap) / 2);
  let g = '';
  semanas.forEach((w, i) => {
    const h = FASE_H[w.fase] || 50, x = x0 + i * (pw + gap), y = cy - h / 2;
    const st = todasFeitas || i < atual ? 'feita' : i === atual ? 'agora' : 'depois';
    const fill = st === 'depois' ? 'var(--surface)' : FASE_COR[w.fase] || FASE_COR.accum;
    const stroke = st === 'depois' || w.deload ? 'var(--plate-edge)' : FASE_COR[w.fase] || FASE_COR.accum;
    g += `<rect x="${x}" y="${y}" width="${pw}" height="${h}" rx="4" fill="${fill}" stroke="${stroke}" stroke-width="2"${st === 'depois' ? ' stroke-dasharray="4 3"' : ''}/>`;
    if (st === 'agora') g += `<rect x="${x - 4}" y="${y - 4}" width="${pw + 8}" height="${h + 8}" rx="7" fill="none" stroke="var(--accent)" stroke-width="2.5"/>`;
    g += `<text x="${x + pw / 2}" y="${H - 4}" text-anchor="middle" font-size="13" font-weight="700" font-family="Barlow Condensed, Arial Narrow, sans-serif" fill="${st === 'agora' ? 'var(--accent)' : 'var(--muted)'}">${t('wk')}${i + 1}</text>`;
  });
  const fim = x0 + semanas.length * (pw + gap) + 4;
  return `<svg class="bar-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(semanas[atual] ? nomeFase(semanas[atual].fase) : '')}"><rect x="6" y="${cy - 3}" width="${W - 12}" height="6" rx="3" fill="var(--bar)"/><rect x="${x0 - 18}" y="${cy - 15}" width="9" height="30" rx="2" fill="var(--bar)"/>${g}<rect x="${fim}" y="${cy - 9}" width="10" height="18" rx="2" fill="var(--bar)"/></svg>`;
}
const legendaFases = () => `<div class="row small muted">${Object.entries(FASE_COR).map(([f, c]) => `<span class="row" style="gap:5px"><i style="width:10px;height:10px;border-radius:2px;background:${c};border:1px solid var(--plate-edge);display:inline-block"></i>${esc(nomeFase(f))}</span>`).join('')}</div>`;

/* ---------- welcome ---------- */
function viewWelcome() {
  const demo = ['adapt', 'accum', 'accum', 'intens', 'deload'].map(f => ({ fase: f, deload: f === 'deload' }));
  return `<section class="screen">
    <div class="seg">${LANGS.map(([c, n]) => `<button data-a="setIdioma" data-v="${c}" aria-pressed="${LANG() === c}">${n}</button>`).join('')}</div>
    <div class="hero">
      <p class="eyebrow">${t('welcome_eyebrow')}</p>
      <div class="marca"><img src="${MARCA_PNG}" alt="" width="72" height="68"><h1 class="h-display h1">Swordbell</h1></div>
      ${barbell(demo, 1, false)}
      <p class="lead">${t('welcome_lead')}</p>
      <button class="btn big block" data-a="novoPerfil">${t('create_profile')}</button>
    </div>
    <div class="card pad stack" id="comoFunciona"><h2 class="h3">${t('how_it_works')}</h2>
      <ol class="stack small" style="margin:0;padding-left:20px"><li>${t('how1')}</li><li>${t('how2')}</li><li>${t('how3')}</li><li>${t('how4')}</li></ol></div>
  </section>`;
}

/* ---------- profile wizard ---------- */
const WZ_PASSOS = 9;
function novoWizard(edit) {
  const padrao = { nome: '', objetivo: '', foco: [], nivel: '', dias: 4, minutos: 60, sexo: '', idade: '', peso: '', altura: '', cintura: '', pescoco: '', quadril: '', limites: [], limitesTxt: '', gosta: '', evita: '', cardioVezes: 2, cardioModos: [], cardioQuando: 'tanto' };
  S.wizard = { step: 0, d: edit ? { ...padrao, ...clone(S.perfis[edit]) } : padrao, edit: edit || null };
  S.sub = 'wizard';
}
const optBtn = (k, v, nome, desc, on) => `<button class="opt" data-a="wzSet" data-k="${k}" data-v="${esc(v)}" aria-pressed="${on}"><b>${esc(nome)}</b>${desc ? `<span>${esc(desc)}</span>` : ''}</button>`;
const segBtns = (k, vals, atual) => `<div class="seg">${vals.map(v => `<button data-a="wzSet" data-k="${k}" data-v="${v}" data-num="1" aria-pressed="${String(atual) === String(v)}">${v}</button>`).join('')}</div>`;
const chipsMulti = (k, lista, sel) => `<div class="chips">${lista.map(r => `<button class="chip" data-a="wzToggle" data-k="${k}" data-v="${r[0]}" aria-pressed="${sel.includes(r[0])}">${esc(L3(r.slice(1)))}</button>`).join('')}</div>`;
const chipsUm = (k, lista, sel) => `<div class="chips">${lista.map(r => `<button class="chip" data-a="wzSet" data-k="${k}" data-v="${r[0]}" aria-pressed="${sel === r[0]}">${esc(L3(r.slice(1)))}</button>`).join('')}</div>`;
function viewWizard() {
  const { step, d, edit } = S.wizard;
  const q = (e, titulo, corpo) => `<p class="eyebrow">${e}</p><h1 class="h-display h2">${titulo}</h1>${corpo}`;
  let html = '';
  switch (step) {
    case 0: html = q(edit ? t('wz_edit') : t('wz_new'), t('wz_name_q'), `<label class="f" for="wz-nome">${t('wz_name')}<input class="inp" id="wz-nome" data-in="wz" data-k="nome" maxlength="30" autocomplete="given-name" value="${esc(d.nome)}" placeholder="${t('wz_name_ph')}"></label>${edit ? '' : aceiteHTML(d)}`); break;
    case 1: html = q(t('wz_goal_e'), t('wz_goal_q'), `<div class="stack">${OBJETIVOS.map(o => optBtn('objetivo', o.id, L3(o.nome), L3(o.desc), d.objetivo === o.id)).join('')}</div>`); break;
    case 2: html = q(t('wz_focus_e'), t('wz_focus_q'), `<p class="muted small">${t('wz_focus_note')}</p>${chipsMulti('foco', FOCOS, d.foco)}`); break;
    case 3: html = q(t('wz_level_e'), t('wz_level_q'), `<div class="stack">${NIVEIS.map(o => optBtn('nivel', o.id, L3(o.nome), L3(o.desc), d.nivel === o.id)).join('')}</div>`); break;
    case 4: html = q(t('wz_routine_e'), t('wz_routine_q'), `<div class="stack"><p class="small muted">${t('wz_days')}</p>${segBtns('dias', [2, 3, 4, 5, 6], d.dias)}<p class="small muted">${t('wz_minutes')}</p>${segBtns('minutos', [30, 45, 60, 75, 90], d.minutos)}</div>`); break;
    case 5: html = q(t('wz_body_e'), t('wz_body_q'), `<p class="small muted">${t('wz_body_note')}</p>${chipsUm('sexo', SEXOS, d.sexo)}
      <div class="grid2">
        <label class="f" for="wz-idade">${t('wz_age')}<input class="inp num" id="wz-idade" data-in="wz" data-k="idade" inputmode="numeric" maxlength="3" value="${esc(d.idade)}" placeholder="${t('ph_years')}"></label>
        <label class="f" for="wz-peso">${t('wz_weight')}<input class="inp num" id="wz-peso" data-in="wz" data-k="peso" inputmode="decimal" maxlength="5" value="${esc(d.peso)}" placeholder="kg"></label>
        <label class="f" for="wz-altura">${t('wz_height')}<input class="inp num" id="wz-altura" data-in="wz" data-k="altura" inputmode="numeric" maxlength="3" value="${esc(d.altura)}" placeholder="cm"></label>
      </div>
      ${medidasCamposHTML(d, 'wz')}
      <div class="card pad" id="wz-comp">${composicaoHTML(d)}</div>`); break;
    case 6: html = q(t('wz_care_e'), t('wz_care_q'), `<p class="small muted">${t('wz_care_note')}</p>${chipsMulti('limites', LIMITES, d.limites)}
      <label class="f" for="wz-lim">${t('wz_care_more')}<textarea class="inp" id="wz-lim" data-in="wz" data-k="limitesTxt" maxlength="300" placeholder="${t('wz_care_ph')}">${esc(d.limitesTxt)}</textarea></label>`); break;
    case 7: html = q(t('wz_cardio_e'), t('wz_cardio_q'), `<p class="small muted">${t('wz_cardio_times')}</p>${segBtns('cardioVezes', [0, 1, 2, 3, 4, 5], d.cardioVezes)}
      ${d.cardioVezes ? `<p class="small muted">${t('wz_cardio_likes')}</p>${chipsMulti('cardioModos', CARDIO_MODOS, d.cardioModos)}<p class="small muted">${t('wz_cardio_when')}</p>${chipsUm('cardioQuando', CARDIO_QUANDO, d.cardioQuando)}` : `<p class="small muted">${t('wz_cardio_none')}</p>`}`); break;
    case 8: html = q(t('wz_likes_e'), t('wz_likes_q'), `<label class="f" for="wz-gosta">${t('wz_likes')}<textarea class="inp" id="wz-gosta" data-in="wz" data-k="gosta" maxlength="200" placeholder="${t('wz_likes_ph')}">${esc(d.gosta)}</textarea></label>
      <label class="f" for="wz-evita">${t('wz_avoid')}<textarea class="inp" id="wz-evita" data-in="wz" data-k="evita" maxlength="200" placeholder="${t('wz_avoid_ph')}">${esc(d.evita)}</textarea></label>`); break;
  }
  const ult = step === WZ_PASSOS - 1;
  return `<section class="screen">
    <div class="row between"><span class="small muted num">${t('wz_step', { a: step + 1, b: WZ_PASSOS })}</span><button class="btn quiet small" data-a="wzSair">${t('cancel')}</button></div>
    <div class="xp-track" aria-hidden="true"><div class="xp-fill" style="width:${((step + 1) / WZ_PASSOS) * 100}%"></div></div>
    <div class="stack">${html}</div>
    <div class="row" style="flex-wrap:nowrap">${step > 0 ? `<button class="btn ghost" data-a="wzVoltar">${t('back')}</button>` : ''}<button class="btn block" data-a="wzAvancar">${ult ? t('wz_save') : t('continue')}</button></div>
  </section>`;
}
function wzValida() {
  const { step, d } = S.wizard;
  if (step === 0 && !d.nome.trim()) return t('wz_err_name');
  if (step === 0 && !S.wizard.edit && !aceitouPerfil(d)) return t('consent_err');
  if (step === 1 && !d.objetivo) return t('wz_err_goal');
  if (step === 3 && !d.nivel) return t('wz_err_level');
  return '';
}
async function salvarPerfil() {
  const w = S.wizard, d = w.d, pid = w.edit || uid('p'), atual = S.perfis[pid] || {};
  const body = { ...atual, ...d, nome: d.nome.trim().slice(0, 30), lang: LANG(), atualizadoEm: Date.now(), criadoEm: atual.criadoEm || Date.now() };
  body.medidas = novaMedida(atual, body);
  try { await save('perfis/' + pid, body, w.edit ? t('profile_saved') : ''); } catch { return; }
  if (!S.perfis[pid]) { S.perfis[pid] = body; S.ordem.push(pid); } else S.perfis[pid] = body;
  S.wizard = null;
  if (S.me !== pid) setMe(pid);
  const temGym = S.gym && (S.gym.itens || []).length;
  S.sub = temGym ? null : 'gym';
  if (!temGym) S.gymDraft = null;
  S.tab = 'plano';
  render();
}

